_report_cache = {}

_report_cache_lock = _threading.Lock()



def _cached_report(key, ttl, builder):
    """Serve an expensive per-fleet report from a short-lived cache. The dashboard polls every
    5s and these reports take 25-55s to build, so without this every poll stacked another full
    computation. Stale-while-revalidate: once expired, callers still get the previous value
    instantly while ONE background thread rebuilds it; only the very first call ever waits."""
    import time
    hit = _report_cache.get(key)
    if hit and time.time() - hit[0] < ttl:
        return hit[1]

    def _build():
        value = builder()
        _report_cache[key] = (time.time(), value)
        return value

    if hit:  # stale: refresh in background, answer now
        if _report_cache_lock.acquire(blocking=False):
            def _refresh():
                try:
                    _build()
                except Exception:
                    import traceback; traceback.print_exc()
                finally:
                    _report_cache_lock.release()
            _threading.Thread(target=_refresh, daemon=True).start()
        return hit[1]
    with _report_cache_lock:  # cold: first caller builds, the rest wait for it
        hit = _report_cache.get(key)
        return hit[1] if hit else _build()



