@router.get("/api/scan/coverage")
def get_scan_coverage():
    """Returns vulnerability breakdown by scan engine (nuclei/zap/secrets/spiderfoot/...)."""
    try:
        with db_manager.get_db_cursor(cursor_factory=RealDictCursor) as cur:
            cur.execute("""
                SELECT
                    COALESCE(scan_engine, 'nuclei') as engine,
                    COUNT(*) as total,
                    COUNT(CASE WHEN COALESCE(real_severity, severity) IN ('CRITICAL','HIGH') THEN 1 END) as high_critical,
                    COUNT(CASE WHEN status = 'NEW' THEN 1 END) as new_findings
                FROM public.vulnerability_log
                GROUP BY COALESCE(scan_engine, 'nuclei')
                ORDER BY total DESC
            """)
            rows = cur.fetchall()

            cur.execute("""
                SELECT
                    COALESCE(scan_engine, 'nuclei') as engine,
                    COUNT(DISTINCT asset_id) as assets_covered
                FROM public.vulnerability_log
                GROUP BY COALESCE(scan_engine, 'nuclei')
            """)
            coverage = {r["engine"]: r["assets_covered"] for r in cur.fetchall()}

            return {
                "scan_engines": [dict(r) for r in rows],
                "assets_covered_per_engine": coverage,
                "total_vulnerabilities": sum(r["total"] for r in rows)
            }
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))



@router.get("/api/compliance/audit")
def run_compliance_audit(target_dir: Optional[str] = "/app"):
    """Ejecuta la auditoría de Estándares Integrales (STRIDE + ISO 25010) sobre el código.

    Rewritten 2026-09-08: the previous body imported a class `AuditorComplianceStandards`
    that this module has never exported (it only has module-level functions), so this
    endpoint returned a 500 on every single call. Now calls the real
    `run_compliance_standards_audit()` and attributes findings to a real self-audit asset,
    matching `/api/audit/full-spectrum`'s pattern (see its comment for the asset_id / `/app`
    reasoning).
    """
    try:
        from auditors import auditor_compliance_standards

        asset_id = resolve_self_audit_asset_id(target_dir)
        findings = auditor_compliance_standards.run_compliance_standards_audit(target_dir, asset_id=asset_id)

        by_severity: Dict[str, int] = {}
        by_rule: Dict[str, int] = {}
        for f in findings:
            sev = str(f.get("severity", "UNKNOWN")).upper()
            by_severity[sev] = by_severity.get(sev, 0) + 1
            rule = f.get("cve_id", "UNKNOWN")
            by_rule[rule] = by_rule.get(rule, 0) + 1

        return {
            "status": "success",
            "target_dir": target_dir,
            "asset_id": asset_id,
            "total": len(findings),
            "by_severity": by_severity,
            "by_rule": dict(sorted(by_rule.items(), key=lambda kv: kv[1], reverse=True)),
            "findings": findings,
        }
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Error en auditoría de estándares: {str(e)}")



